	private static IRI iri(String local) {
		return VF.createIRI(EX, local);
	}

	private static String opt(String cond) {
		return "SELECT ?s ?v ?w { ?s :p ?v OPTIONAL { ?s :q ?w FILTER(" + cond + ") } }";
	}

	static Stream<Arguments> admitted() {
		return Stream.of(
				Arguments.of("?w > ?v", opt("?w > ?v")),
				Arguments.of("?w = ?v", opt("?w = ?v")),
				Arguments.of("?w != ?v", opt("?w != ?v")),
				Arguments.of("?v = <const> (left names only)", opt("?v = :a8")),
				Arguments.of("sameTerm(?v, ?w)", opt("sameTerm(?v, ?w)")),
				Arguments.of("!isLiteral(?w) || ?w > ?v", opt("!isLiteral(?w) || ?w > ?v")),
				Arguments.of("str(?w) = str(?v)", opt("str(?w) = str(?v)")),
				Arguments.of("lang(?w) = en || ?v = <const>", opt("lang(?w) = \"en\" || ?v = :a8")),
				Arguments.of("datatype(?w) = xsd:integer || ?w = ?v", opt("datatype(?w) = xsd:integer || ?w = ?v")),
				Arguments.of("isURI(?w) || isBlank(?w) || ?w < ?v", opt("isURI(?w) || isBlank(?w) || ?w < ?v")),
				Arguments.of("BOUND(?v) && ?w > ?v", opt("BOUND(?v) && ?w > ?v")),
				Arguments.of("type error: ?w > ?v on strings", opt("?w > ?v || ?w < ?v")),
				Arguments.of("two chained conditioned OPTIONALs",
						"SELECT ?s ?v ?w ?z { ?s :p ?v OPTIONAL { ?s :q ?w FILTER(?w > ?v) } "
								+ "OPTIONAL { ?s :r ?z FILTER(?z > ?v) } }"),
				Arguments.of("projection subset s,w",
						"SELECT ?s ?w { ?s :p ?v OPTIONAL { ?s :q ?w FILTER(?w > ?v) } }"));
	}

	/** Reported, not prescribed: bag and origin facts must match; the route is printed. */
	static Stream<Arguments> reported() {
		return Stream.of(
				Arguments.of("?w > 5 && ?v < 9", opt("?w > 5 && ?v < 9")),
				Arguments.of("projection subset s,v (no boundary is taken)",
						"SELECT ?s ?v { ?s :p ?v OPTIONAL { ?s :q ?w FILTER(?w > ?v) } }"),
				Arguments.of("nested OPTIONAL with conditions",
						"SELECT ?s ?v ?w ?z { ?s :p ?v OPTIONAL { ?s :q ?w FILTER(?w > ?v) OPTIONAL { ?s :r ?z FILTER(?z > ?w) } } }"),
				Arguments.of("shared var both sides", "SELECT ?s ?v { ?s :p ?v OPTIONAL { ?s :q ?v FILTER(?v > 2) } }"),
				Arguments.of("non-well-designed with a resource name used outside",
						"SELECT ?s ?v ?x ?z { { ?s :p ?v OPTIONAL { ?s :q ?x FILTER(?x > ?v) } } ?x :r ?z }"));
	}

	/**
	 * Conditions over right-side names only (and the right-only conjunct of a split conjunction) are relocated by the
	 * optimizer into the right arm as a Filter node; they are not LeftJoin conditions and stay out of the sealed route.
	 * Only the bag and "not sealed" are asserted here: origin-fact parity of a relocated right-arm filter has a Q0
	 * mismatch for some filters and is covered by NativeRelocatedOptionalFilterOriginScratchTest.
	 */
	static Stream<Arguments> relocated() {
		return Stream.of(
				Arguments.of("lang(?w) = en (right-only)", opt("lang(?w) = \"en\"")),
				Arguments.of("datatype(?w) = xsd:integer && ?w != ?v (split)",
						opt("datatype(?w) = xsd:integer && ?w != ?v")),
				Arguments.of("regex(str(?w), a) (right-only)", opt("regex(str(?w), \"a\")")),
				Arguments.of("isNumeric(?w) && ?w + 1 > ?v (split)", opt("isNumeric(?w) && ?w + 1 > ?v")),
				Arguments.of("?w > 5 (right-only)", opt("?w > 5")));
	}

	static Stream<Arguments> refused() {
		return Stream.of(
				// Paired guards: "neither side" and the sibling shapes pin the domain rule together with the physical
				// readable-mask check; the BIND shape pins the assured rule together with the physical assured check.
				// Each single guard alone is shadowed by the other, so removing both is what turns these cases red.
				Arguments.of("variable produced by neither side", opt("?w > ?nope")),
				Arguments.of("EXISTS in the condition", opt("EXISTS { ?s :r ?z } || ?w > ?v")),
				Arguments.of("function call in the condition", opt("strlen(str(?w)) > ?v")),
				Arguments.of("regex(str(?w), a) || ?v = <const> (regex parses to a FunctionCall)",
						opt("regex(str(?w), \"a\") || ?v = :a8")),
				Arguments.of("right arm with two patterns (condition becomes a MultiJoin filter)",
						"SELECT ?s ?v ?w ?z { ?s :p ?v OPTIONAL { ?s :q ?w . ?s :r ?z FILTER(?w > ?v) } }"),
				Arguments.of("condition variable bound only by a later join sibling",
						"SELECT ?s ?v ?w ?z { { ?s :p ?v OPTIONAL { ?s :q ?w FILTER(?w > ?z) } } ?s :r ?z }"),
				Arguments.of("condition variable bound only by an earlier join sibling",
						"SELECT ?s ?v ?w ?z { ?s :r ?z { ?s :p ?v OPTIONAL { ?s :q ?w FILTER(?w > ?z) } } }"),
				Arguments.of("BIND of an optional-side name over a conditioned OPTIONAL",
						"SELECT ?s ?x { ?s :p ?v OPTIONAL { ?s :q ?w FILTER(?w > ?v) } BIND(?w AS ?x) }"),
				Arguments.of("right side is a subselect",
						"SELECT ?s ?v ?w { ?s :p ?v OPTIONAL { { SELECT ?s ?w WHERE { ?s :q ?w } } FILTER(?w > ?v) } }"),
				Arguments.of("non-well-designed: right-only name used outside",
						"SELECT ?s ?v ?w ?t { { ?s :p ?v OPTIONAL { ?s :q ?w FILTER(?w > ?v) } } ?t :r ?w }"));
	}

	private void assertDifferential(String label, String query) {
		assertEquals(bag(query, false, null), bag(query, true, null), "native bag equals ordinary bag: " + label);
		assertEquals(rowsWithProvenance(query, false, null), rowsWithProvenance(query, true, null),
				"row origin facts: " + label);
	}

	private static String sealedLine(String explain) {
		int at = explain.indexOf("SealedProjection(");
		if (at < 0) {
			return null;
		}
		int end = explain.indexOf('\n', at);
		return explain.substring(at, end < 0 ? explain.length() : end);
	}

