	@Test
	void aCallerBoundInputKeepsBagAndOriginFactsAndIsNotSealed() {
		String query = opt("?w > ?v");
		for (Map.Entry<String, Value> input : Map.of("w", (Value) VF.createLiteral(10), "v", VF.createLiteral(5))
				.entrySet()) {
			Map<String, Value> binding = Map.of(input.getKey(), input.getValue());
			assertEquals(bag(query, false, binding), bag(query, true, binding), "bag with input " + input.getKey());
			assertEquals(rowsWithProvenance(query, false, binding), rowsWithProvenance(query, true, binding),
					"origin facts with input " + input.getKey());
			assertFalse(explain(query, binding).contains("SealedProjection("),
					"not sealed with input " + input.getKey());
		}
	}

	/** The four row kinds, each with its exact origin facts, on the sealed route. */
	@Test
	void eachOfTheFourRowKindsOccursWithItsOriginFacts() {
		String query = opt("?w > ?v");
		Map<Row, Integer> sealed = rowsWithProvenance(query, true, null);
		Map<Row, Integer> ordinary = rowsWithProvenance(query, false, null);
		assertEquals(ordinary, sealed, "origin facts");
		Set<String> withW = Set.of("s", "v", "w"), withoutW = Set.of("s", "v");
		assertKind(sealed, "a1", withoutW, false); // no right match
		assertKind(sealed, "a2", withW, true); // matched and true
		assertKind(sealed, "a3", withoutW, false); // matched and false (q = 1 is not > 5)
		assertKind(sealed, "a4", withoutW, false); // matched and error (string against integer)
	}

	private static void assertKind(Map<Row, Integer> rows, String subject, Set<String> locals, boolean hasW) {
		boolean seen = false;
		for (Row row : rows.keySet()) {
			if (iri(subject).equals(row.values().get("s"))) {
				seen = true;
				assertEquals(locals, row.locals(), "locals of " + subject);
				assertEquals(hasW, row.values().containsKey("w"), "w bound for " + subject);
				assertTrue(row.tracked(), "tracked for " + subject);
				assertTrue(row.requests().isEmpty(), "no requests for " + subject);
			}
		}
		assertTrue(seen, "row kind occurs for " + subject);
	}

	private record Row(Map<String, Value> values, boolean tracked, Set<String> requests, Set<String> locals,
			Map<String, Value> parameters, Map<String, Value> graphs) {
	}

	private Map<Row, Integer> rowsWithProvenance(String query, boolean nativeEngine, Map<String, Value> input) {
		System.setProperty(FLAG, Boolean.toString(nativeEngine));
		TupleExpr parsed = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, PREFIX + query, null).getTupleExpr();
		TupleExpr root = parsed instanceof QueryRoot ? parsed.clone() : new QueryRoot(parsed.clone());
		org.eclipse.rdf4j.query.impl.MapBindingSet bindings = new org.eclipse.rdf4j.query.impl.MapBindingSet();
		if (input != null) {
			input.forEach(bindings::setBinding);
		}
		Map<Row, Integer> result = new HashMap<>();
		try (SailRepositoryConnection c = repository.getConnection();
				var rows = c.getSailConnection()
						.evaluate(root, null,
								input == null ? EmptyBindingSet.getInstance() : bindings, true)) {
			while (rows.hasNext()) {
				BindingSet row = rows.next();
				Map<String, Value> values = new LinkedHashMap<>();
				for (String name : row.getBindingNames()) {
					values.put(name, row.getValue(name));
				}
				BindingSetOrigin origin = BindingSetOrigin.of(row);
				result.merge(new Row(Collections.unmodifiableMap(values), BindingSetOrigin.isTrackedInput(row),
						Set.copyOf(origin.requestNames()), Set.copyOf(origin.localNames()),
						Collections.unmodifiableMap(new LinkedHashMap<>(origin.retainedParametersForTransport())),
						Collections.unmodifiableMap(new LinkedHashMap<>(
								GraphFrameBindings.from(row).retainedParametersForTransport()))),
						1, Integer::sum);
			}
		}
		return result;
	}

	private Map<Map<String, Value>, Integer> bag(String query, boolean nativeEngine, Map<String, Value> input) {
		System.setProperty(FLAG, Boolean.toString(nativeEngine));
		Map<Map<String, Value>, Integer> result = new HashMap<>();
		try (SailRepositoryConnection c = repository.getConnection()) {
			TupleQuery tq = c.prepareTupleQuery(PREFIX + query);
			if (input != null) {
				input.forEach(tq::setBinding);
			}
			try (TupleQueryResult rows = tq.evaluate()) {
				while (rows.hasNext()) {
					BindingSet row = rows.next();
					Map<String, Value> values = new HashMap<>();
					row.forEach(b -> values.put(b.getName(), b.getValue()));
					result.merge(values, 1, Integer::sum);
				}
			}
		}
		return result;
	}

	private String explain(String query, Map<String, Value> input) {
		System.setProperty(FLAG, "true");
		try (SailRepositoryConnection c = repository.getConnection()) {
			TupleQuery tq = c.prepareTupleQuery(PREFIX + query);
			if (input != null) {
				input.forEach(tq::setBinding);
			}
			return tq.explain(Explanation.Level.Telemetry).toString();
		}
	}
